mapper.select:
SELECT id, user_id AS userId, provider, base_url AS baseUrl, model_name AS modelName, is_active AS isActive, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM user_api_keys WHERE user_id = #{userId}
AND (provider LIKE #{likeKeyword} OR model_name LIKE #{likeKeyword})
ORDER BY provider

mapper.update:
UPDATE user_api_keys
SET base_url = #{baseUrl}, api_key = #{apiKey}, model_name = #{modelName}, is_active = 1
WHERE id = #{id}
